<script setup lang="ts">
import { Text } from '@/shared/ui/text/paragraph';
import { RouterLink } from 'vue-router';
import { onMounted, computed } from 'vue';
import { useStore } from 'vuex';

const store = useStore();

onMounted(() => {
  store.dispatch('projects/fetchProjects');
});
const projectsData = computed(() => store.state.projects?.projectsData);

</script>

<template>
  <div class="project-item" v-for="item in projectsData" :key="item.id">
    <RouterLink :to="`/projects/${item.slug}/`" class="link">
      <div class="image">

        <img :src="item.image" :aria-label="`${item.name}`" />
      </div>
      <Text tagName="p" size="l" color="dark-first" class="title">
        {{ item.title }}
      </Text>
    </RouterLink>
  </div>
</template>

<style scoped lang="scss">
@import './style.scss';
</style>
